import { createReadStream } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { createServer, type Server, type ServerResponse, type IncomingMessage } from "node:http";

export type ReplyFormat = "markdown" | "plain";
export type ResponseMode = "card" | "text";
export type AgentType = "codex" | "pi" | "opencode";
export interface AgentModels { codex: string; pi: string; opencode: string; }

export function isPiModelAllowed(model: string): boolean {
  return !model.startsWith("nvidia");
}

export function isOpenCodeModelAllowed(model: string): boolean {
  return model.startsWith("opencode") && model.endsWith("-free") || model.startsWith("inke");
}

export function normalizeAgentModel(agent: AgentType, value: string | undefined): string {
  const model = value?.trim() || "";
  if (agent === "opencode") {
    if (!model) return "";
    const normalized = model.includes("/") ? model : model.split(/\s+/).slice(0, 2).join("/");
    return isOpenCodeModelAllowed(normalized) ? normalized : "";
  }
  if (agent === "pi" && !isPiModelAllowed(model)) return "";
  if (agent !== "pi" || !model || model.includes("/")) return model;
  const parts = model.split(/\s+/);
  return parts.length >= 2 ? `${parts[0]}/${parts[1]}` : model;
}
export interface CommandKeywordsConfig {
  pause: string[];
  monitorOpen: string[];
  monitorStop: string[];
  switchPi: string[];
  switchCodex: string[];
  switchOpencode: string[];
}

export interface MonitorTarget { groupId: string; groupName: string; senderId: string; senderName: string; }
export interface DashboardConfig { privateChatEnabled: boolean; responseMode: ResponseMode; cardUpdateIntervalMs: number; showElapsed: boolean; showProcessingDetails: boolean; agentModels: AgentModels; personalHistoryMessageLimit: number; personalHistoryPollIntervalSeconds: number; personalHistoryLookbackMinutes: number; webhookUrl: string; targets: MonitorTarget[]; botAllowedUserIds: string[]; botAllowedUserNames?: Record<string, string>; botSuperAdminUserIds: string[]; botSuperAdminUserNames?: Record<string, string>; robotSenderOpenDingTalkId?: string; commandKeywords: CommandKeywordsConfig; groupPromptSuffix: string; replyFormat: ReplyFormat; robotName: string; clientId: string; clientSecret: string; agent: AgentType; }
interface PublicDashboardConfig extends Omit<DashboardConfig, "clientSecret" | "webhookUrl"> { clientSecretConfigured: boolean; webhookConfigured: boolean; }
export interface ConversationMessage { senderName: string; senderId: string; content: string; createdAt?: string; }
export interface ReplyRecord { id: string; createdAt: string; conversationType: "group" | "personal"; conversationName?: string; groupId: string; groupName: string; status: "processing" | "completed" | "failed"; agent?: AgentType; question?: string; senderNames?: string[]; senderDetails?: ConversationMessage[]; content: string; messageCount: number; }
export interface DashboardStatus { startedAt: string; eventConnected: boolean; lastEventAt?: string; activeBatches: number; }
export interface GroupMatch { groupId: string; groupName: string; memberCount?: number; }
export interface GroupMember { senderId: string; senderName: string; role?: string; }
export interface UserMatch { senderId: string; senderName: string; department?: string; }
export interface BotMatch { openDingTalkId: string; name: string; }
export interface CurrentDwsUser { userId?: string; openDingTalkId?: string; name?: string; email?: string; dept?: string; org?: string; auth?: Record<string, unknown>; }
export interface SystemProcessStatus { role: string; pid: number; ppid?: number; running: boolean; command?: string; }
export interface SystemMonitorStatus { mode: string; startedAt?: string; workspace?: string; processes: SystemProcessStatus[]; checkedAt: string; }

export interface DashboardHooks {
  getConfig: () => DashboardConfig;
  updateConfig: (config: DashboardConfig) => Promise<void>;
  getStatus: () => DashboardStatus;
  getReplies: () => ReplyRecord[];
  searchGroups: (query: string) => Promise<GroupMatch[]>;
  listGroupMembers: (groupId: string) => Promise<GroupMember[]>;
  searchUsers: (query: string) => Promise<UserMatch[]>;
  searchBots?: (query: string) => Promise<BotMatch[]>;
  getCurrentDwsUser?: () => Promise<CurrentDwsUser>;
  getDwsAuthStatus?: () => Promise<Record<string, unknown>>;
  startDwsDeviceLogin?: () => { started: boolean; message: string };
  getDwsDeviceLoginOutput?: () => Promise<{ running: boolean; output: string }>;
  logoutDws?: () => Promise<void>;
  getBotStatus?: () => Promise<{ enabled: boolean; connected: boolean; updatedAt?: string }>;
  getSystemStatus?: () => Promise<SystemMonitorStatus>;
  getSystemLogs?: (offset?: number) => Promise<{ content: string; path: string; size: number; nextOffset: number; reset: boolean }>;
  restartSystem?: () => Promise<void>;
  controlSystemProcess?: (role: string, action: "start" | "stop") => Promise<void>;
  listAgentModels?: (agent: AgentType) => Promise<{ models: string[]; defaultModel?: string }>;
}

export interface DashboardAuth {
  isAuthenticated: (request: IncomingMessage) => boolean;
  login: (password: string) => Promise<string | null>;
  logout: (request: IncomingMessage) => void;
  changePassword: (request: IncomingMessage, currentPassword: string, newPassword: string) => Promise<string | null>;
}

export interface DashboardServerOptions {
  host?: string;
  version?: string;
  auth: DashboardAuth;
}

function sendJson(response: ServerResponse, status: number, value: unknown, headers: Record<string, string> = {}): void {
  response.writeHead(status, { "content-type": "application/json; charset=utf-8", "cache-control": "no-store", ...headers });
  response.end(JSON.stringify(value));
}

function publicConfig(config: DashboardConfig): PublicDashboardConfig {
  const { clientSecret, webhookUrl, ...rest } = config;
  return { ...rest, clientSecretConfigured: Boolean(clientSecret), webhookConfigured: Boolean(webhookUrl) };
}

function normalizeConfig(value: unknown): DashboardConfig {
  if (!value || typeof value !== "object") throw new Error("配置必须是 JSON 对象");
  const source = value as { privateChatEnabled?: unknown; responseMode?: unknown; cardUpdateIntervalMs?: unknown; showElapsed?: unknown; showProcessingDetails?: unknown; agentModel?: unknown; agentModels?: unknown; personalHistoryMessageLimit?: unknown; personalHistoryPollIntervalSeconds?: unknown; personalHistoryLookbackMinutes?: unknown; webhookUrl?: unknown; targets?: unknown; botAllowedUserIds?: unknown; botAllowedUserNames?: unknown; botSuperAdminUserIds?: unknown; botSuperAdminUserNames?: unknown; robotSenderOpenDingTalkId?: unknown; commandKeywords?: unknown; groupPromptSuffix?: unknown; groupPromptPrefix?: unknown; replyFormat?: unknown; robotName?: unknown; clientId?: unknown; clientSecret?: unknown; robotCode?: unknown; agent?: unknown };
  if (source.privateChatEnabled !== undefined && typeof source.privateChatEnabled !== "boolean") throw new Error("个人私聊开关格式无效");
  if (source.cardUpdateIntervalMs !== undefined && !Number.isFinite(source.cardUpdateIntervalMs)) throw new Error("卡片更新间隔格式无效");
  const cardUpdateIntervalMs = source.cardUpdateIntervalMs === undefined
    ? 3_000
    : Number(source.cardUpdateIntervalMs) <= 0
      ? 0
    : Number(source.cardUpdateIntervalMs) <= 60
      ? Number(source.cardUpdateIntervalMs) * 1_000
      : Number(source.cardUpdateIntervalMs);
  if (cardUpdateIntervalMs !== 0 && (cardUpdateIntervalMs < 1_000 || cardUpdateIntervalMs > 60_000)) throw new Error("卡片更新间隔需为 0（完成后一次性发送）或 1-60 秒");
  const responseMode: ResponseMode = source.responseMode === "text" ? "text" : "card";
  if (source.showElapsed !== undefined && typeof source.showElapsed !== "boolean") throw new Error("总耗时显示开关格式无效");
  const positiveInteger = (value: unknown, fallback: number, name: string) => { const n = value === undefined ? fallback : Number(value); if (!Number.isInteger(n) || n < 1 || n > 500) throw new Error(`${name}需为 1-500 的整数`); return n; };
  const agentModel = source.agentModel === undefined ? "" : String(source.agentModel).trim();
  if (agentModel.length > 200) throw new Error("Agent 模型名称过长");
  const modelSource = source.agentModels && typeof source.agentModels === "object" ? source.agentModels as { codex?: unknown; pi?: unknown; opencode?: unknown } : {};
  const agentModels: AgentModels = {
    codex: (typeof modelSource.codex === "string" ? modelSource.codex.trim() : "") || (source.agent === "codex" ? agentModel : ""),
    pi: normalizeAgentModel("pi", (typeof modelSource.pi === "string" ? modelSource.pi.trim() : "") || (source.agent === "pi" ? agentModel : "")),
    opencode: normalizeAgentModel("opencode", (typeof modelSource.opencode === "string" ? modelSource.opencode.trim() : "") || (source.agent === "opencode" ? agentModel : "")),
  };
  if (agentModels.codex.length > 200 || agentModels.pi.length > 200 || agentModels.opencode.length > 200) throw new Error("Agent 模型名称过长");
  const personalHistoryMessageLimit = positiveInteger(source.personalHistoryMessageLimit, 10, "每次消息数量");
  const personalHistoryPollIntervalSeconds = source.personalHistoryPollIntervalSeconds === undefined ? 15 : Number(source.personalHistoryPollIntervalSeconds);
  if (!Number.isFinite(personalHistoryPollIntervalSeconds) || personalHistoryPollIntervalSeconds < 0 || personalHistoryPollIntervalSeconds > 3600) throw new Error("个人群消息拉取间隔需为 0-3600 秒");
  const personalHistoryLookbackMinutes = source.personalHistoryLookbackMinutes === undefined ? 10 : Number(source.personalHistoryLookbackMinutes);
  if (!Number.isInteger(personalHistoryLookbackMinutes) || personalHistoryLookbackMinutes < 1 || personalHistoryLookbackMinutes > 60) throw new Error("个人群消息拉取时间范围需为 1-60 分钟");
  const webhookUrl = source.webhookUrl === undefined ? "" : String(source.webhookUrl).trim();
  if (webhookUrl && (!webhookUrl.startsWith("https://oapi.dingtalk.com/robot/send") || webhookUrl.length > 2_000)) throw new Error("机器人 Webhook 地址格式无效");
  if (!Array.isArray(source.targets)) throw new Error("钉钉规则格式无效");
  const keys = new Set<string>();
  const targets = source.targets.map((item, index) => {
    if (!item || typeof item !== "object") throw new Error(`第 ${index + 1} 条钉钉规则无效`);
    const candidate = item as Partial<MonitorTarget>;
    const target: MonitorTarget = {
      groupId: candidate.groupId?.trim() ?? "", groupName: candidate.groupName?.trim() ?? "",
      senderId: candidate.senderId?.trim() ?? "", senderName: candidate.senderName?.trim() ?? "",
    };
    if (!target.groupId || !target.groupName || !target.senderId || !target.senderName) {
      throw new Error(`第 ${index + 1} 条规则的群或人员信息不完整`);
    }
    const key = `${target.groupId}:${target.senderId}`;
    if (keys.has(key)) throw new Error(`第 ${index + 1} 条规则重复`);
    keys.add(key);
    return target;
  });
  if (source.replyFormat !== "markdown" && source.replyFormat !== "plain") throw new Error("回复格式只能是 markdown 或 plain");
  if (source.agent !== "codex" && source.agent !== "pi" && source.agent !== "opencode") throw new Error("Agent 只能是 Codex CLI、Pi Agent 或 OpenCode");
  if (!Array.isArray(source.botAllowedUserIds)) throw new Error("请至少配置一名机器人单聊授权人员");
  const botAllowedUserIds = [...new Set(source.botAllowedUserIds.filter((id): id is string => typeof id === "string").map((id) => id.trim()).filter(Boolean))];
  // The dashboard is also the first-run setup screen. Allow an incomplete
  // draft to be saved so a fresh machine can be configured before the bot
  // worker has credentials or DWS login.
  if (typeof source.robotName !== "string") throw new Error("机器人名称格式无效");
  if (typeof source.clientId !== "string") throw new Error("Client ID 格式无效");
  if (typeof source.clientSecret !== "string") throw new Error("Client Secret 格式无效");
  const botAllowedUserNames = source.botAllowedUserNames && typeof source.botAllowedUserNames === "object"
    ? Object.fromEntries(Object.entries(source.botAllowedUserNames).filter((entry): entry is [string, string] => typeof entry[0] === "string" && typeof entry[1] === "string"))
    : {};
  const botSuperAdminUserIds = Array.isArray(source.botSuperAdminUserIds)
    ? [...new Set(source.botSuperAdminUserIds.filter((id): id is string => typeof id === "string").map((id) => id.trim()).filter(Boolean))]
    : [];
  if (botSuperAdminUserIds.some((id) => !botAllowedUserIds.includes(id))) throw new Error("Session 超级管理员必须同时是机器人单聊授权人员");
  const botSuperAdminUserNames = source.botSuperAdminUserNames && typeof source.botSuperAdminUserNames === "object"
    ? Object.fromEntries(Object.entries(source.botSuperAdminUserNames).filter((entry): entry is [string, string] => typeof entry[0] === "string" && typeof entry[1] === "string"))
    : {};
  if (!source.commandKeywords || typeof source.commandKeywords !== "object") throw new Error("请配置消息指令关键词");
  const commandSource = source.commandKeywords as Record<string, unknown>;
  const keywordList = (key: string): string[] => {
    if (!Array.isArray(commandSource[key])) return [];
    const values = [...new Set(commandSource[key].filter((item): item is string => typeof item === "string").map((item) => item.trim()).filter(Boolean))];
    return values;
  };
  const commandKeywords: CommandKeywordsConfig = {
    pause: keywordList("pause"), monitorOpen: keywordList("monitorOpen"), monitorStop: keywordList("monitorStop"),
    switchPi: keywordList("switchPi"), switchCodex: keywordList("switchCodex"), switchOpencode: keywordList("switchOpencode"),
  };
  const groupPromptSuffix = typeof source.groupPromptSuffix === "string" ? source.groupPromptSuffix : source.groupPromptPrefix;
  if (typeof groupPromptSuffix !== "string") throw new Error("消息后缀格式无效");
  return { privateChatEnabled: source.privateChatEnabled === true, responseMode, cardUpdateIntervalMs, showElapsed: source.showElapsed !== false, showProcessingDetails: source.showProcessingDetails === true, agentModels, personalHistoryMessageLimit, personalHistoryPollIntervalSeconds, personalHistoryLookbackMinutes, webhookUrl, targets, botAllowedUserIds, botAllowedUserNames, botSuperAdminUserIds, botSuperAdminUserNames, robotSenderOpenDingTalkId: typeof source.robotSenderOpenDingTalkId === "string" ? source.robotSenderOpenDingTalkId.trim() : "", commandKeywords, groupPromptSuffix: groupPromptSuffix.trim(), replyFormat: source.replyFormat, robotName: source.robotName.trim(), clientId: source.clientId.trim(), clientSecret: source.clientSecret.trim(), agent: source.agent };
}

export function startDashboard(port: number, hooks: DashboardHooks, options: DashboardServerOptions): Server {
  const host = options.host?.trim() || "127.0.0.1";
  const modelSettingsScript = String.raw`<script>
(() => {
  const agentSettings = document.querySelector('.agent-settings');
  if (!agentSettings) return;
  const style = document.createElement('style');
  style.textContent = '.agent-settings .prompt-inline-field{width:100%;margin-top:26px}.agent-settings .prompt-inline-field textarea{display:block;width:100%;min-height:120px;height:120px;padding:10px 11px;border:1px solid #c9d3e0;border-radius:5px;background:#fff;color:#172033;font:13px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace;resize:vertical}.agent-settings .prompt-inline-field textarea:focus{outline:2px solid #b9d7ff;border-color:#1677ff}.agent-settings .prompt-inline-field .prompt-help{margin-top:6px;color:#657287;font-size:12px;line-height:1.5}';
  document.head.append(style);
  const panel = document.createElement('div');
  panel.className = 'agent-model-settings';
  const responsePanel = document.createElement('div');
  responsePanel.className = 'response-mode-settings';
  responsePanel.innerHTML = '<div class="field"><label>Agent 回复方式</label><div class="agent-options"><label><input type="radio" name="responseMode" value="card" checked> 互动卡片</label><label><input type="radio" name="responseMode" value="text"> 普通文本</label></div><div class="field-help">群聊和私聊统一使用此方式。普通文本只在 Agent 完成后发送最终结果。</div></div>';
  agentSettings.querySelector('.agent-row')?.append(responsePanel);
  const cardIntervalInput = document.querySelector('#cardUpdateIntervalMs');
  if (cardIntervalInput) {
    cardIntervalInput.min = '0';
    cardIntervalInput.max = '60';
    cardIntervalInput.step = '1';
    const field = cardIntervalInput.closest('.compact-number-field');
    if (field?.lastChild?.nodeType === Node.TEXT_NODE) {
      field.lastChild.textContent = ' 秒（0：完成后一次性发送，1-60：按间隔更新）';
    }
  }
  panel.innerHTML = '<div class="field"><label>Pi 默认模型</label><select id="piModel"><option value="">使用 Pi CLI 默认模型</option></select><div class="field-help">群聊和私聊使用 Pi 时都采用此模型。</div></div><div class="field" style="margin-top:14px"><label>OpenCode 默认模型</label><select id="opencodeModel"><option value="">使用 OpenCode CLI 默认模型</option></select><div class="field-help">模型来自 OpenCode CLI，格式为 provider/model。</div></div>';
  agentSettings.querySelector('.agent-row')?.append(panel);
  const loadModels = async (agent) => {
    const select = document.querySelector('#' + agent + 'Model');
    if (!select) return;
    const selected = select.value;
    try {
      const response = await fetch('/api/agent-models?agent=' + encodeURIComponent(agent), { cache: 'no-store' });
      const body = await response.json();
      if (!response.ok) throw new Error(body.error || '模型列表读取失败');
      const defaultModel = typeof body.defaultModel === 'string' ? body.defaultModel : '';
      select.replaceChildren(new Option(defaultModel && agent === 'opencode' ? '使用 OpenCode CLI 默认模型（' + defaultModel + '）' : agent === 'codex' ? '使用 Codex CLI 默认模型' : agent === 'opencode' ? '使用 OpenCode CLI 默认模型' : '使用 Pi CLI 默认模型', ''));
      body.models.forEach((model) => select.append(new Option(model, model)));
      const selectedAllowed = agent === 'codex' || agent === 'pi' && !selected.startsWith('nvidia') || agent === 'opencode' && ((selected.startsWith('opencode') && selected.endsWith('-free')) || selected.startsWith('inke'));
      if (selected && selectedAllowed && ![...select.options].some((option) => option.value === selected)) select.append(new Option(selected + '（当前配置）', selected));
      select.value = selected || (agent === 'opencode' ? defaultModel : '');
    } catch (error) {
      select.replaceChildren(new Option((agent === 'codex' ? 'Codex' : agent === 'opencode' ? 'OpenCode' : 'Pi') + ' 模型列表不可用，请检查 CLI', ''));
      if (selected) select.append(new Option(selected + '（当前配置）', selected));
      select.value = selected;
      select.title = error instanceof Error ? error.message : String(error);
    }
  };
  const loadState = async () => {
    const response = await fetch('/api/state', { cache: 'no-store' });
    const body = await response.json();
    const models = body.config?.agentModels || {};
    const intervalInput = document.querySelector('#cardUpdateIntervalMs');
    if (intervalInput && body.config?.cardUpdateIntervalMs !== undefined) {
      intervalInput.value = String(body.config.cardUpdateIntervalMs / 1000);
    }
    const responseMode = body.config?.responseMode === 'text' ? 'text' : 'card';
    document.querySelectorAll('input[name=responseMode]').forEach((input) => { input.checked = input.value === responseMode; });
    document.querySelector('#piModel').value = models.pi || '';
    await loadModels('pi');
    document.querySelector('#opencodeModel').value = models.opencode || '';
    await loadModels('opencode');
  };
  const nativeFetch = window.fetch.bind(window);
  window.fetch = (input, init) => {
    const url = typeof input === 'string' ? input : input.url;
    if (url.endsWith('/api/config') && init?.method === 'PUT' && typeof init.body === 'string') {
      try {
        const body = JSON.parse(init.body);
        body.agentModels = {
          codex: '',
          pi: document.querySelector('#piModel')?.value || '',
          opencode: document.querySelector('#opencodeModel')?.value || '',
        };
        body.commandKeywords = {
          ...body.commandKeywords,
          switchOpencode: (document.querySelector('#keywordsSwitchOpencode')?.value || '').split(/[|｜]+/).map((value) => value.trim()).filter(Boolean),
        };
        body.responseMode = document.querySelector('input[name=responseMode]:checked')?.value === 'text' ? 'text' : 'card';
        body.showProcessingDetails = document.querySelector('#showProcessingDetails')?.checked === true;
        const intervalValue = document.querySelector('#cardUpdateIntervalMs')?.value;
        if (intervalValue !== undefined && intervalValue !== '' && Number.isFinite(Number(intervalValue))) {
          body.cardUpdateIntervalMs = Number(intervalValue) * 1000;
        }
        init = { ...init, body: JSON.stringify(body) };
      } catch {}
    }
    return nativeFetch(input, init).then((response) => {
      if (response.status === 401 && !String(url).endsWith('/api/login')) { window.location.href = '/login'; }
      return response;
    });
  };
  void loadState();
  setInterval(async () => {
    const input = document.querySelector('#cardUpdateIntervalMs');
    if (!input || document.activeElement === input) return;
    try {
      const response = await nativeFetch('/api/state', { cache: 'no-store' });
      const body = await response.json();
      if (body.config?.cardUpdateIntervalMs !== undefined) input.value = String(body.config.cardUpdateIntervalMs / 1000);
    } catch {}
  }, 500);
})();
</script>`;
  const dashboardPage = PAGE.replace('value="pi"> Pi Agent</label>', 'value="pi"> Pi Agent</label><label><input type="radio" name="agent" value="opencode"> OpenCode Agent</label>')
    .replace('<div class="field"><label>切换到 Pi 指令</label><input type="text" id="keywordsSwitchPi" placeholder="例如：切pi|切换pi|换pi"></div>', '<div class="field"><label>切换到 Pi 指令</label><input type="text" id="keywordsSwitchPi" placeholder="例如：切pi|切换pi|换pi"></div><div class="field"><label>切换到 OpenCode 指令</label><input type="text" id="keywordsSwitchOpencode" placeholder="例如：切opencode|切换opencode|换opencode"></div>')
    .replace('</body></html>', modelSettingsScript + '</body></html>');
  const server = createServer((request, response) => {
    const url = new URL(request.url ?? "/", "http://127.0.0.1");
    const readBody = (): Promise<string> => new Promise((resolve, reject) => { let body = ""; request.setEncoding("utf8"); request.on("data", (chunk: string) => { body += chunk; if (body.length > 10_000) reject(new Error("请求内容过大")); }); request.on("end", () => resolve(body)); request.on("error", reject); });
    if (request.method === "POST" && url.pathname === "/api/login") {
      void readBody().then((body) => { let password = ""; try { password = String((JSON.parse(body) as { password?: unknown }).password ?? ""); } catch { /* invalid body */ } return options.auth.login(password); }).then((token) => token ? sendJson(response, 200, { loggedIn: true }, { "set-cookie": `omi_session=${token}; HttpOnly; SameSite=Strict; Path=/` }) : sendJson(response, 401, { error: "密码错误" })).catch(() => sendJson(response, 400, { error: "请求无效" }));
      return;
    }
    if (request.method === "POST" && url.pathname === "/api/logout") { options.auth.logout(request); sendJson(response, 200, { loggedOut: true }, { "set-cookie": "omi_session=; HttpOnly; SameSite=Strict; Path=/; Max-Age=0" }); return; }
    if (url.pathname === "/login") { response.writeHead(200, { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" }); response.end(LOGIN_PAGE); return; }
    if (url.pathname.startsWith("/api/") && url.pathname !== "/api/login" && !options.auth.isAuthenticated(request)) { sendJson(response, 401, { error: "未登录" }); return; }
    if (url.pathname === "/" && !options.auth.isAuthenticated(request)) { response.writeHead(302, { location: "/login" }); response.end(); return; }
    if (request.method === "GET" && url.pathname === "/favicon.ico") {
      response.writeHead(200, { "content-type": "image/x-icon", "cache-control": "public, max-age=86400" });
      createReadStream(join(dirname(fileURLToPath(import.meta.url)), "..", "outputs", "favicon", "favicon.ico")).pipe(response);
      return;
    }
    if (request.method === "GET" && url.pathname === "/assets/favicon-32.png") {
      response.writeHead(200, { "content-type": "image/png", "cache-control": "public, max-age=86400" });
      createReadStream(join(dirname(fileURLToPath(import.meta.url)), "..", "outputs", "favicon", "favicon-32.png")).pipe(response);
      return;
    }
    if (request.method === "GET" && url.pathname === "/assets/omi-icon.png") {
      response.writeHead(200, { "content-type": "image/png", "cache-control": "public, max-age=86400" });
      createReadStream(join(dirname(fileURLToPath(import.meta.url)), "..", "outputs", "omi-icon.png")).pipe(response);
      return;
    }
    if (request.method === "GET" && url.pathname === "/") {
      response.writeHead(200, { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" });
      response.end(dashboardPage.replaceAll("__OMI_VERSION__", options.version ? `v${options.version.replace(/^v/i, "")}` : "unknown"));
      return;
    }
    if (request.method === "GET" && url.pathname === "/favicon.ico") {
      response.writeHead(204, { "cache-control": "public, max-age=86400" });
      response.end();
      return;
    }
    if (request.method === "POST" && url.pathname === "/api/password") {
      void readBody().then((body) => { const value = JSON.parse(body) as { currentPassword?: unknown; newPassword?: unknown }; return options.auth.changePassword(request, String(value.currentPassword ?? ""), String(value.newPassword ?? "")); }).then((error) => error ? sendJson(response, 400, { error }) : sendJson(response, 200, { changed: true })).catch(() => sendJson(response, 400, { error: "请求无效" })); return;
    }
    if (request.method === "GET" && url.pathname === "/api/state") {
      sendJson(response, 200, { config: publicConfig(hooks.getConfig()), status: hooks.getStatus(), replies: hooks.getReplies().slice(0, 10) });
      return;
    }
    if (request.method === "GET" && url.pathname === "/api/agent-models") {
      if (!hooks.listAgentModels) return sendJson(response, 501, { error: "Agent 模型查询不可用" });
      const requestedAgent = url.searchParams.get("agent");
      const agent = requestedAgent === "pi" || requestedAgent === "opencode" ? requestedAgent : "codex";
      void hooks.listAgentModels(agent).then((result) => sendJson(response, 200, result)).catch((err) => sendJson(response, 500, { error: err instanceof Error ? err.message : String(err) }));
      return;
    }
    if (request.method === "GET" && url.pathname === "/api/system-status") {
      if (!hooks.getSystemStatus) return sendJson(response, 501, { error: "系统监控不可用" });
      void hooks.getSystemStatus().then((status) => sendJson(response, 200, { status })).catch((err) => sendJson(response, 500, { error: err instanceof Error ? err.message : String(err) }));
      return;
    }
    if (request.method === "GET" && url.pathname === "/api/system-logs") {
      if (!hooks.getSystemLogs) return sendJson(response, 501, { error: "系统日志不可用" });
      const rawOffset = url.searchParams.get("offset");
      const offset = rawOffset === null ? undefined : Number(rawOffset);
      void hooks.getSystemLogs(Number.isFinite(offset) && offset! >= 0 ? offset : undefined).then((logs) => sendJson(response, 200, logs)).catch((err) => sendJson(response, 500, { error: err instanceof Error ? err.message : String(err) }));
      return;
    }
    if (request.method === "POST" && url.pathname === "/api/system-restart") {
      if (!hooks.restartSystem) return sendJson(response, 501, { error: "系统重启不可用" });
      void hooks.restartSystem().then(() => sendJson(response, 202, { restarting: true })).catch((err) => sendJson(response, 500, { error: err instanceof Error ? err.message : String(err) }));
      return;
    }
    const processAction = url.pathname.match(/^\/api\/system-process\/([^/]+)\/(start|stop)$/);
    if (request.method === "POST" && processAction) {
      if (!hooks.controlSystemProcess) return sendJson(response, 501, { error: "进程控制不可用" });
      const role = decodeURIComponent(processAction[1]);
      if (!["group-worker", "bot"].includes(role)) return sendJson(response, 400, { error: "不允许控制该进程" });
      void hooks.controlSystemProcess(role, processAction[2] as "start" | "stop").then(() => sendJson(response, 202, { accepted: true })).catch((err) => sendJson(response, 500, { error: err instanceof Error ? err.message : String(err) }));
      return;
    }
    if (request.method === "GET" && url.pathname === "/api/users") {
      const query = url.searchParams.get("q")?.trim() ?? "";
      if (!query) return sendJson(response, 400, { error: "请输入钉钉人名" });
      void hooks.searchUsers(query).then((users) => sendJson(response, 200, { users })).catch((err) => {
        sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) });
      });
      return;
    }
      if (request.method === "GET" && url.pathname === "/api/bot-status") {
      if (!hooks.getBotStatus) return sendJson(response, 501, { error: "机器人状态查询不可用" });
      void hooks.getBotStatus().then((status) => sendJson(response, 200, { status })).catch((err) => sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) }));
      return;
    }
    if (request.method === "GET" && url.pathname === "/api/dws-auth-status") {
      if (!hooks.getDwsAuthStatus) return sendJson(response, 501, { error: "DWS 认证状态查询不可用" });
      void hooks.getDwsAuthStatus().then((status) => sendJson(response, 200, { status })).catch((err) => sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) }));
      return;
    }
    if (request.method === "POST" && url.pathname === "/api/dws-device-login") {
      if (!hooks.startDwsDeviceLogin) return sendJson(response, 501, { error: "DWS Device Flow 不可用" });
      return sendJson(response, 200, hooks.startDwsDeviceLogin());
    }
    if (request.method === "GET" && url.pathname === "/api/dws-device-login") {
      if (!hooks.getDwsDeviceLoginOutput) return sendJson(response, 501, { error: "DWS Device Flow 不可用" });
      void hooks.getDwsDeviceLoginOutput().then((result) => sendJson(response, 200, result)).catch((err) => sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) }));
      return;
    }
    if (request.method === "POST" && url.pathname === "/api/dws-logout") {
      if (!hooks.logoutDws) return sendJson(response, 501, { error: "DWS 退出登录不可用" });
      void hooks.logoutDws().then(() => sendJson(response, 200, { loggedOut: true })).catch((err) => sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) }));
      return;
    }
    if (request.method === "GET" && url.pathname === "/api/current-user") {
      if (!hooks.getCurrentDwsUser) return sendJson(response, 501, { error: "当前 DWS 登录账号查询不可用" });
      void hooks.getCurrentDwsUser().then((user) => sendJson(response, 200, { user })).catch((err) => {
        sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) });
      });
      return;
    }
    if (request.method === "GET" && url.pathname === "/api/bots") {
      const query = url.searchParams.get("q")?.trim() ?? "";
      if (!query) return sendJson(response, 400, { error: "请输入机器人名称" });
      if (!hooks.searchBots) return sendJson(response, 501, { error: "机器人搜索功能不可用" });
      void hooks.searchBots(query).then((bots) => sendJson(response, 200, { bots })).catch((err) => {
        sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) });
      });
      return;
    }
    if (request.method === "GET" && url.pathname === "/api/groups") {
      const query = url.searchParams.get("q")?.trim() ?? "";
      if (!query) return sendJson(response, 400, { error: "请输入群名称" });
      void hooks.searchGroups(query).then((groups) => sendJson(response, 200, { groups })).catch((err) => {
        sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) });
      });
      return;
    }
    const membersMatch = url.pathname.match(/^\/api\/groups\/([^/]+)\/members$/);
    if (request.method === "GET" && membersMatch) {
      void hooks.listGroupMembers(decodeURIComponent(membersMatch[1])).then((members) => sendJson(response, 200, { members })).catch((err) => {
        sendJson(response, 502, { error: err instanceof Error ? err.message : String(err) });
      });
      return;
    }
    if (request.method === "PUT" && url.pathname === "/api/config") {
      let body = "";
      request.setEncoding("utf8");
      request.on("data", (chunk: string) => { body += chunk; });
      request.on("end", () => {
        try {
          if (body.length > 100_000) throw new Error("请求内容过大");
          const config = normalizeConfig(JSON.parse(body));
          if (!config.clientSecret) config.clientSecret = hooks.getConfig().clientSecret;
          if (!config.webhookUrl) config.webhookUrl = hooks.getConfig().webhookUrl;
          console.log(`[Dashboard] saving config agent=${config.agent} targets=${config.targets.length} botUsers=${config.botAllowedUserIds.length}`);
          void hooks.updateConfig(config).then(() => {
            console.log(`[Dashboard] config saved agent=${config.agent} targets=${config.targets.length}`);
            sendJson(response, 200, { config: publicConfig(config), saved: true });
          }).catch((err) => {
            console.error(`[Dashboard] config save failed: ${err instanceof Error ? err.message : String(err)}`);
            sendJson(response, 500, { error: err instanceof Error ? err.message : String(err) });
          });
        } catch (err) {
          sendJson(response, 400, { error: err instanceof Error ? err.message : String(err) });
        }
      });
      return;
    }
    sendJson(response, 404, { error: "Not found" });
  });
  server.listen(port, host);
  return server;
}

